-- What supabase/challenge_rounds.sql does, tried inside the rolled-back
-- transaction of a dry run: nothing here is kept.
--
--   set -a; . ./.env; set +a
--   PG_MODULE=/tmp/pg/node_modules/pg/lib/index.js \
--     node tools/apply_sql.mjs supabase/challenge_rounds.sql --dry --try=tools/challenge_rounds_try.sql --table=challenge_shortlist
--
-- Made-up accounts, made and gone with the transaction: Ada, Bob and Dan design
-- (13 or over, profiles), Ed votes, Cy is under 13, Jo is the guest judge (a
-- profile). Every model a test model, so the challenge is a test one, which no
-- visitor's page shows. Each statement is on one line: the dry run splits at a
-- semicolon that ends a line. Inside one transaction now() never moves, so the
-- rounds are moved by moving their days.
create function pg_temp.tries(statement text) returns text language plpgsql as $$ begin execute statement; return 'allowed'; exception when others then return 'refused: ' || sqlerrm; end $$;
create temp table before_ as select md5(coalesce(public.gallery_pick(false)::text, '')) as pick, md5(coalesce(public.challenge_page(false)::text, '')) as page;
update public.challenges set ended_at = now() where test and ended_at is null;
insert into auth.users (id, instance_id, aud, role, email) values ('00000000-0000-4000-8000-0000000000d1', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'rounds-ada@resend.dev'), ('00000000-0000-4000-8000-0000000000d2', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'rounds-bob@resend.dev'), ('00000000-0000-4000-8000-0000000000d3', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'rounds-cy@resend.dev'), ('00000000-0000-4000-8000-0000000000d4', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'rounds-dan@resend.dev'), ('00000000-0000-4000-8000-0000000000d5', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'rounds-ed@resend.dev'), ('00000000-0000-4000-8000-0000000000d7', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'rounds-jo@resend.dev');
select public.answer_age('00000000-0000-4000-8000-0000000000d1', true)->>'over_13' as ada, public.answer_age('00000000-0000-4000-8000-0000000000d2', true)->>'over_13' as bob, public.answer_age('00000000-0000-4000-8000-0000000000d3', false)->>'over_13' as cy, public.answer_age('00000000-0000-4000-8000-0000000000d4', true)->>'over_13' as dan, public.answer_age('00000000-0000-4000-8000-0000000000d5', true)->>'over_13' as ed, public.answer_age('00000000-0000-4000-8000-0000000000d7', true)->>'over_13' as jo;
insert into public.people (account, handle, name) values ('00000000-0000-4000-8000-0000000000d1', 'rounds-try-ada', 'Ada Try'), ('00000000-0000-4000-8000-0000000000d2', 'rounds-try-bob', 'Bob Try'), ('00000000-0000-4000-8000-0000000000d4', 'rounds-try-dan', 'Dan Try'), ('00000000-0000-4000-8000-0000000000d7', 'rounds-try-jo', 'Jo Judge');
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, published) values ('RoundTry01', '00000000-0000-4000-8000-0000000000d1', 'Ada one', 'Ada Try', 40, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('RoundTry02', '00000000-0000-4000-8000-0000000000d1', 'Ada two', 'Ada Try', 40, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('RoundTry03', '00000000-0000-4000-8000-0000000000d1', 'Ada three', 'Ada Try', 40, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('RoundTry04', '00000000-0000-4000-8000-0000000000d2', 'Bob one', 'Bob Try', 40, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('RoundTry05', '00000000-0000-4000-8000-0000000000d2', 'Bob two', 'Bob Try', 40, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('RoundTry06', '00000000-0000-4000-8000-0000000000d2', 'Bob three', 'Bob Try', 40, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('RoundTry07', '00000000-0000-4000-8000-0000000000d4', 'Dan one', 'Dan Try', 40, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('RoundTry08', '00000000-0000-4000-8000-0000000000d4', 'Dan secret', 'Dan Try', 40, 100, false, null, true, now() - interval '3 days', true);
-- A test challenge with no rules but its brief, open since yesterday.
select public.challenge_set('Try rounds', 'Build anything, judged then voted.', current_date - 1, current_date + 12, test => true) ?| array['challenge'] as "set";
-- One round until rounds are set: challenge_round says null, and nothing is shortlisted.
select public.challenge_round(c) is null as "one round", public.challenge_shortlist_set(c.id, array['RoundTry01'])->>'refused' as "a shortlist in one round" from public.challenges c where c.title = 'Try rounds';
-- Rounds, judge and cover: refused in words for each reason.
select public.challenge_rounds_set(c.id, current_date + 2, null)->>'refused' as "one day of two", public.challenge_rounds_set(c.id, current_date + 2, current_date + 2)->>'refused' as "vote on the last entry day", public.challenge_rounds_set(c.id, current_date - 5, current_date + 3)->>'refused' as "entries before its first day", public.challenge_rounds_set(c.id, current_date + 2, current_date + 20)->>'refused' as "vote after its last day", public.challenge_rounds_set(c.id, current_date + 2, current_date + 5, judge_handle => 'no-such-person-here')->>'refused' as "no such judge", public.challenge_rounds_set(c.id, current_date + 2, current_date + 5, cover_model => 'RoundTry08')->>'refused' as "a cover not in the gallery", public.challenge_rounds_set(c.id, current_date + 2, current_date + 5, judge_name => repeat('x', 61))->>'refused' as "a long judge's name", public.challenge_rounds_set(999999999, null, null)->>'refused' as "no challenge" from public.challenges c where c.title = 'Try rounds';
select public.challenge_rounds_set(c.id, current_date + 2, current_date + 5, judge_handle => 'rounds-try-jo', cover_model => 'RoundTry01')->'rounds' as "set: entries for 3 days, vote from day 6" from public.challenges c where c.title = 'Try rounds';
-- Entries come in while entries are open: seven, six of them by hand from three designers.
select public.challenge_enter_round('00000000-0000-4000-8000-0000000000d1', 'RoundTry01', 'hand')->>'entered' as a1, public.challenge_enter_round('00000000-0000-4000-8000-0000000000d1', 'RoundTry02', 'hand')->>'entered' as a2, public.challenge_enter_round('00000000-0000-4000-8000-0000000000d1', 'RoundTry03', 'hand')->>'entered' as a3, public.challenge_enter_round('00000000-0000-4000-8000-0000000000d2', 'RoundTry04', 'hand')->>'entered' as b1, public.challenge_enter_round('00000000-0000-4000-8000-0000000000d2', 'RoundTry05', 'hand')->>'entered' as b2, public.challenge_enter_round('00000000-0000-4000-8000-0000000000d2', 'RoundTry06', 'assistant')->>'entered' as b3, public.challenge_enter_round('00000000-0000-4000-8000-0000000000d4', 'RoundTry07', 'hand')->>'entered' as d1;
-- The rules of before still hold through it: one entered twice is refused, as challenge_enter refuses it.
select public.challenge_enter_round('00000000-0000-4000-8000-0000000000d1', 'RoundTry01', 'hand')->>'refused' as "entered already";
-- While entries come in: no shortlist, and no vote.
select c.id > 0 as here, public.challenge_round(c) as round, public.challenge_shortlist_set(c.id, array['RoundTry01'])->>'refused' as "a shortlist now", public.challenge_vote_round('00000000-0000-4000-8000-0000000000d5', c.id, 'RoundTry01', true)->>'refused' as "a vote now" from public.challenges c where c.title = 'Try rounds';
-- Entries close (their last day was yesterday) and the judges choose: no more entries, still no vote.
select public.challenge_rounds_set(c.id, current_date - 1, current_date + 1, judge_handle => 'rounds-try-jo', cover_model => 'RoundTry01')->'rounds'->>'round' as round from public.challenges c where c.title = 'Try rounds';
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, published) values ('RoundTry09', '00000000-0000-4000-8000-0000000000d4', 'Dan late', 'Dan Try', 40, 100, true, now(), true, now(), true);
select public.challenge_enter_round('00000000-0000-4000-8000-0000000000d4', 'RoundTry09', 'hand') as "entered late", public.challenge_vote_round('00000000-0000-4000-8000-0000000000d5', c.id, 'RoundTry01', true) as "a vote while judging" from public.challenges c where c.title = 'Try rounds';
-- The shortlist: refused for six in a group, for a model not entered; then two by hand and one with the assistant.
select public.challenge_shortlist_set(c.id, array['RoundTry01', 'RoundTry02', 'RoundTry03', 'RoundTry04', 'RoundTry05', 'RoundTry07']) as "six by hand", public.challenge_shortlist_set(c.id, array['RoundTry01', 'RoundTry09']) as "one not entered" from public.challenges c where c.title = 'Try rounds';
select public.challenge_shortlist_set(c.id, array['RoundTry01', 'RoundTry04', 'RoundTry06', 'RoundTry01']) as "the shortlist" from public.challenges c where c.title = 'Try rounds';
-- Out before the vote opens: visitors see it, and the vote waits for its day.
select r->>'round' as round, r->'shortlist' as shortlist, r->'judge' as judge, r->'cover'->>'id' as cover from (select public.challenge_rounds_of(c.id) as r from public.challenges c where c.title = 'Try rounds') x;
-- The fan vote opens today; its days and the shortlist then stay as they are.
select public.challenge_rounds_set(c.id, current_date - 1, current_date, judge_handle => 'rounds-try-jo', cover_model => 'RoundTry01')->'rounds'->>'round' as round from public.challenges c where c.title = 'Try rounds';
select public.challenge_rounds_set(c.id, current_date - 1, current_date + 1)->>'refused' as "days moved in the vote", public.challenge_shortlist_set(c.id, array['RoundTry02'])->>'refused' as "shortlist changed in the vote", public.challenge_rounds_set(c.id, current_date - 1, current_date, judge_name => 'Brickworks')->'rounds'->'judge' as "the judge may change" from public.challenges c where c.title = 'Try rounds';
select public.challenge_rounds_set(c.id, current_date - 1, current_date, judge_handle => 'rounds-try-jo', cover_model => 'RoundTry01')->'rounds'->'judge' as "the judge again" from public.challenges c where c.title = 'Try rounds';
-- Votes: only for the shortlist; the rules of before (one in each group, never your own, none under 13) as they were.
select public.challenge_vote_round('00000000-0000-4000-8000-0000000000d5', c.id, 'RoundTry02', true)->>'refused' as "Ed, not shortlisted", public.challenge_vote_round('00000000-0000-4000-8000-0000000000d5', c.id, 'RoundTry01', true)->>'voted' as "Ed, Ada's", public.challenge_vote_round('00000000-0000-4000-8000-0000000000d5', c.id, 'RoundTry04', true)->>'refused' as "Ed, a second by hand", public.challenge_vote_round('00000000-0000-4000-8000-0000000000d5', c.id, 'RoundTry06', true)->>'voted' as "Ed, Bob's by the assistant", public.challenge_vote_round('00000000-0000-4000-8000-0000000000d2', c.id, 'RoundTry01', true)->>'voted' as "Bob, Ada's", public.challenge_vote_round('00000000-0000-4000-8000-0000000000d1', c.id, 'RoundTry01', true)->>'refused' as "Ada, her own", public.challenge_vote_round('00000000-0000-4000-8000-0000000000d3', c.id, 'RoundTry04', true)->>'refused' as "Cy", public.challenge_vote_round('00000000-0000-4000-8000-0000000000d5', c.id, 'RoundTry01', false)->>'refused' as "not a test account" from public.challenges c where c.title = 'Try rounds';
-- Blind as before: the page says no votes while it runs.
select bool_and(e->'votes' = 'null'::jsonb) as "no votes shown while open" from public.challenges c, jsonb_array_elements(public.challenge_page_at(c.id, true)->'entries') e where c.title = 'Try rounds';
-- A vote for an entry not shortlisted, put in by hand, is never counted: Dan's has three.
insert into public.challenge_votes (challenge, way, voter, model) select c.id, 'hand', v.id, 'RoundTry07' from public.challenges c, (values ('00000000-0000-4000-8000-0000000000d1'::uuid), ('00000000-0000-4000-8000-0000000000d3'::uuid), ('00000000-0000-4000-8000-0000000000d7'::uuid)) v(id) where c.title = 'Try rounds';
-- It ends: Ada's (2 votes) wins by hand and Bob's (1) with the assistant; both are the pick, a week each, the most voted first.
select public.challenge_end(c.id) as ended, public.challenge_settle_rounds(c.id) as settled, public.challenge_settle_rounds(c.id) as "settled again" from public.challenges c where c.title = 'Try rounds';
select w.way, w.model, w.votes from public.challenge_winners w join public.challenges c on c.id = w.challenge where c.title = 'Try rounds' order by w.way desc;
select p.model, p.chosen_at = now() as "from now", round(extract(epoch from p.until - p.chosen_at) / 86400) as days, round(extract(epoch from p.chosen_at - now()) / 86400) as "days from now" from public.gallery_picks p where p.model like 'RoundTry%' order by p.chosen_at;
select public.gallery_pick(true)->'card'->>'id' as "a tests list's pick", public.gallery_pick(true)->>'chosen' as chosen, (select x->>'title' from public.challenge_wins(owner => '00000000-0000-4000-8000-0000000000d1', tests => true) x limit 1) as "Ada's honour";
select public.challenge_settle_due(true) as "due after";
-- A visitor's pick, page and gallery are as they were.
select (select pick from before_) = md5(coalesce(public.gallery_pick(false)::text, '')) as "a visitor's pick the same", (select page from before_) = md5(coalesce(public.challenge_page(false)::text, '')) as "a visitor's challenge the same";
-- Deleted with the account: Jo's goes from the judge (her name kept, her link gone); Bob's entries from the shortlist.
delete from auth.users where id = '00000000-0000-4000-8000-0000000000d7';
select c.judge_name, c.judge_account is null as "no account", (select count(*) from public.challenge_shortlist s where s.challenge = c.id) as shortlisted from public.challenges c where c.title = 'Try rounds';
delete from auth.users where id = '00000000-0000-4000-8000-0000000000d2';
select (select count(*) from public.challenge_shortlist s where s.challenge = c.id) as "shortlisted after Bob" from public.challenges c where c.title = 'Try rounds';
-- Nobody but the service role runs them.
select has_function_privilege('anon', 'public.challenge_rounds_set(bigint, date, date, text, text, text)', 'execute') as anon_set, has_function_privilege('authenticated', 'public.challenge_shortlist_set(bigint, text[])', 'execute') as auth_shortlist, has_function_privilege('authenticated', 'public.challenge_vote_round(uuid, bigint, text, boolean)', 'execute') as auth_vote, has_function_privilege('service_role', 'public.challenge_rounds_of(bigint)', 'execute') as service_reads, has_table_privilege('authenticated', 'public.challenge_shortlist', 'select') as auth_reads_table;
